Button:
(id).setOnClickListener { view ->
val digit = (view as Button).text.toString()
onDigitPressed(digit)
}
}

val operatorIds = mapOf(
R.id.btnAdd to "+",
R.id.btnSubtract to "-",
R.id.btnMultiply to "*",
R.id.btnDivide to "/"
)

for ((id, op) in operatorIds) {
findViewById(id).setOnClickListener {
    onOperatorPressed(op)
    }
    }

    findViewById(R.id.btnEquals).setOnClickListener { onEqualsPressed() }
        findViewById(R.id.btnClear).setOnClickListener { onClearPressed() }
            }

            private fun onDigitPressed(digit: String) {
            if (isNewInput || tvDisplay.text.toString() == "0") {
            tvDisplay.text = digit
            isNewInput = false
            } else {
            tvDisplay.append(digit)
            }
            }

            private fun onOperatorPressed(op: String) {
            firstOperand = tvDisplay.text.toString().toDoubleOrNull() ?: 0.0
            pendingOperator = op
            isNewInput = true
            }

            private fun onEqualsPressed() {
            if (pendingOperator.isEmpty()) return

            val secondOperand = tvDisplay.text.toString().toDoubleOrNull() ?: 0.0
            val result = when (pendingOperator) {
            "+" -> firstOperand + secondOperand
            "-" -> firstOperand - secondOperand
            "*" -> firstOperand * secondOperand
            "/" -> if (secondOperand != 0.0) firstOperand / secondOperand else Double.NaN
            else -> 0.0
            }

            tvDisplay.text = when {
            result.isNaN() -> "Error"
            result % 1.0 == 0.0 -> result.toLong().toString()
            else -> result.toString()
            }

            pendingOperator = ""
            isNewInput = true
            }

            private fun onClearPressed() {
            tvDisplay.text = "0"
            firstOperand = 0.0
            pendingOperator = ""
            isNewInput = true
            }
            }
